// Copies the static renderer assets (HTML, CSS, plain-JS app and demo data) into dist/renderer.
// The TypeScript renderer scripts (renderer.ts, sim.ts) are compiled there by tsc.
const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
const srcDir = path.join(root, 'src', 'renderer');
const outDir = path.join(root, 'dist', 'renderer');
fs.mkdirSync(outDir, { recursive: true });
for (const f of ['index.html', 'styles.css', 'logo.css', 'logo-marks.js', 'app.js', 'autofollow.js', 'harnesses.js', 'signin.js', 'demo.js', 'markdown.js', 'dialog.js', 'innerscroll.js', 'sessionname.js', 'inlinename.js', 'sessionsearch.js', 'convsearch.js', 'usagetotals.js', 'costtable.js', 'modelswitch.js', 'schedtemplates.js', 'places.js', 'newfolder.js', 'floornav.js', 'cuttext.js', 'chattrim.js', 'subretire.js', 'slashsuggest.js', 'notes.js', 'orgwords.js', 'notesscreen.js', 'probe.js', 'grantlabel.js', 'whyallowed.js', 'sandboxtext.js', 'mcpwords.js', 'editview.js', 'place-icons.js', 'mood.js', 'retry.js', 'attention.js', 'unread.js', 'keys.js', 'activity.js', 'toolstats.js', 'theme.js', 'themes.css', 'scenekits.js', 'screens.js', 'screens.css', 'activitytable.js', 'gitstatus.js', 'sessionsummary.js', 'checkpoints.js', 'exports-shim.js', 'liveact.js', 'lookalike.js', 'safetext.js', 'helpercard.js', 'foldersetup.js', 'navigator.js', 'settingsnav.js', 'autopilot.js', 'crew.js', 'composersize.js', 'ctxbreakdown.js', 'shutters.js', 'coffeebreak.js', 'profileeditor.js', 'simclock.js', 'schedtop.js', 'schedhist.js', 'browserpane.js', 'tooltip.js', 'simcrew.js', 'reorder.js', 'railorder.js', 'realoffice.js', 'realoffice.css', 'realoffice-world.css', 'flatlook.js', 'teams.js']) {
  fs.copyFileSync(path.join(srcDir, f), path.join(outDir, f));
}
// spec 077: the Cheeky Crew portraits (bundled pictures only; the page's CSP allows img-src 'self'). electron-builder packs dist/**/*, so they ship.
fs.rmSync(path.join(outDir, 'crew'), { recursive: true, force: true }); // no stale picture from an older build
const crewOut = path.join(outDir, 'crew', 'art');
fs.mkdirSync(crewOut, { recursive: true });
for (const f of fs.readdirSync(path.join(srcDir, 'crew', 'art'))) if (f.endsWith('.webp')) fs.copyFileSync(path.join(srcDir, 'crew', 'art', f), path.join(crewOut, f)); // only the pictures: ASSETS.md and the prompt files stay in the repo
// spec 097 FR-060, FR-115, spec 102 FR-205: the Real office packs, one folder per world (realoffice/worlds/<id>/) and per character set
// (realoffice/sets/<id>/), WebP only (ASSETS.md stays in the repo). The page's CSP has no connect-src, so each pack's JSON ships as a script
// (world.js sets self.DurbarRealOfficeWorlds[id], set.js sets self.DurbarRealOfficeSets[id]) that app.js loads only when that world or set
// is shown (FR-061); a world may carry world.css. Which folders exist is data: a new world or set is a new folder.
fs.rmSync(path.join(outDir, 'realoffice'), { recursive: true, force: true });
for (const [kind, json, global] of [['worlds', 'world', 'DurbarRealOfficeWorlds'], ['sets', 'set', 'DurbarRealOfficeSets']]) {
  const kin = path.join(srcDir, 'realoffice', kind);
  if (!fs.existsSync(kin)) continue;
  for (const id of fs.readdirSync(kin)) {
    const dIn = path.join(kin, id);
    if (!fs.statSync(dIn).isDirectory()) continue;
    const dOut = path.join(outDir, 'realoffice', kind, id);
    fs.mkdirSync(dOut, { recursive: true });
    for (const f of fs.readdirSync(dIn)) if (f.endsWith('.webp') || (kind === 'worlds' && f === 'world.css')) fs.copyFileSync(path.join(dIn, f), path.join(dOut, f));
    fs.writeFileSync(path.join(dOut, json + '.js'), `/* generated by scripts/copy-assets.js from src/renderer/realoffice/${kind}/${id}/${json}.json */\nself.${global}=self.${global}||{};self.${global}[${JSON.stringify(id)}]=` + JSON.stringify(JSON.parse(fs.readFileSync(path.join(dIn, json + '.json'), 'utf8'))) + ';\n');
  }
}
// spec 102 FR-302 (T265a): the world previews (realoffice/previews/<id>.webp, taken by scripts/shots-102-previews.js) and their zoom origins, as a script
// like the packs' (self.DurbarWorldPreviews = previews.json); Settings (FR-301) reads them.
{
  const pin = path.join(srcDir, 'realoffice', 'previews'), pout = path.join(outDir, 'realoffice', 'previews');
  if (fs.existsSync(pin)) {
    fs.mkdirSync(pout, { recursive: true });
    for (const f of fs.readdirSync(pin)) if (f.endsWith('.webp')) fs.copyFileSync(path.join(pin, f), path.join(pout, f));
    fs.writeFileSync(path.join(pout, 'previews.js'), '/* generated by scripts/copy-assets.js from src/renderer/realoffice/previews/previews.json */\nself.DurbarWorldPreviews=' + JSON.stringify(JSON.parse(fs.readFileSync(path.join(pin, 'previews.json'), 'utf8'))) + ';\n');
  }
}
// spec 008 FR-179: the app version for the simulator's About label (sim.ts cannot import, and the page's CSP has no connect-src), so a release bump edits package.json only.
fs.writeFileSync(path.join(outDir, 'appversion.js'), require('./appversion').appVersionScript(require(path.join(root, 'package.json')).version));
// spec 111 T008: the shared team-template validator for the page (the simulator's fake of `teams:*` uses the very code main's store uses, so the form never
// learns a rule the store refuses). The compiled CommonJS modules of dist/shared are wrapped, with their relative requires resolved inside one closure, into
// one script that sets self.DurbarTeamCheck = {checkTeamTemplate, copyName, CHANGED_TEXT, MEMBER_ID_RE, nameKey, LIMITS}; the page's shared `self.exports` is not touched. Needs `tsc` to have run.
{
  const sharedOut = path.join(root, 'dist', 'shared');
  const defs = {};
  const todo = ['teamtemplate'];
  while (todo.length) {
    const n = todo.pop();
    if (defs[n]) continue;
    defs[n] = fs.readFileSync(path.join(sharedOut, n + '.js'), 'utf8').replace(/^\/\/# sourceMappingURL=.*$/m, '');
    for (const m of defs[n].matchAll(/require\("\.\/([a-z0-9-]+)"\)/g)) todo.push(m[1]);
  }
  const names = Object.keys(defs).sort();
  const body = names.map((n) => `${JSON.stringify(n)}:function(exports,require){${defs[n]}\n}`).join(',\n');
  fs.writeFileSync(path.join(outDir, 'teamcheck.js'), `/* generated by scripts/copy-assets.js from dist/shared (${names.join(', ')}) */\n(function(){'use strict';const defs={\n${body}};const cache={};` +
    `function req(p){const n=String(p).replace(/^\\.\\//,'');if(cache[n])return cache[n].exports;if(!Object.prototype.hasOwnProperty.call(defs,n))throw new Error('teamcheck: '+n);const m={exports:{}};cache[n]=m;defs[n](m.exports,req);return m.exports;}` +
    `const t=req('teamtemplate'),s=req('skeleton');self.DurbarTeamCheck={checkTeamTemplate:t.checkTeamTemplate,copyName:t.copyName,CHANGED_TEXT:t.CHANGED_TEXT,MEMBER_ID_RE:t.MEMBER_ID_RE,LIMITS:t.LIMITS,nameKey:s.nameKey};})();\n`);
}
// Markdown parser and sanitiser, bundled from node_modules (no CDN); exact versions are pinned in package.json.
const vendor = path.join(outDir, 'vendor');
fs.mkdirSync(vendor, { recursive: true });
fs.copyFileSync(path.join(root, 'node_modules', 'marked', 'lib', 'marked.umd.js'), path.join(vendor, 'marked.js'));
fs.copyFileSync(path.join(root, 'node_modules', 'dompurify', 'dist', 'purify.min.js'), path.join(vendor, 'purify.min.js'));
// spec 008 FR-025: the window icon on Linux (the packaged app reads it from app.asar)
fs.copyFileSync(path.join(root, 'build', 'icon.png'), path.join(root, 'dist', 'icon.png'));
console.log('copied renderer assets -> dist/renderer, icon -> dist/icon.png');
